releases.releases/demo-greeting.json:
{
  "version": "1.0.0",
  "tools": [
    "hello"
  ],
  "template": {
    "schemaVersion": 1,
    "kind": "open-science.connector",
    "name": "demo-greeting",
    "displayName": "Demo Greeting",
    "description": "Returns a greeting using a local Python process.",
    "transport": "stdio",
    "command": "python3",
    "args": [
      "-u",
      "-c",
      "import sys, json\nfor line in sys.stdin:\n    request = json.loads(line)\n    if \"id\" not in request:\n        continue\n    method = request[\"method\"]\n    if method == \"initialize\":\n        result = {\"protocolVersion\": request[\"params\"][\"protocolVersion\"], \"capabilities\": {\"tools\": {}}, \"serverInfo\": {\"name\": \"Demo\", \"version\": \"1.0.0\"}}\n    elif method == \"tools/list\":\n        result = {\"tools\": [{\"name\": \"hello\", \"description\": \"Return a greeting\", \"inputSchema\": {\"type\": \"object\", \"properties\": {}}}]}\n    elif method == \"tools/call\":\n        result = {\"content\": [{\"type\": \"text\", \"text\": \"Hello\"}]}\n    else:\n        result = {}\n    print(json.dumps({\"jsonrpc\": \"2.0\", \"id\": request[\"id\"], \"result\": result}), flush=True)"
    ]
  }
}

